package main

import (
    "log"
    "net/http"
    "os"
    "github.com/joho/godotenv"
    "swing-society-website/server/internal"

    "swing-society-website/server/internal/config"
)

func main() {
    // Load environment variables
    if err := godotenv.Load(); err != nil {
        log.Printf("Warning: .env file not found")
    }

    // Load configuration
    if err := config.LoadConfig(); err != nil {
        log.Fatalf("Failed to load configuration: %v", err)
    }

    // Create router with Google Cloud project ID from config
    projectID := os.Getenv("GOOGLE_CLOUD_PROJECT")
    if projectID == "" {
        projectID = config.AppConfig.External.ProjectID
    }

    router, err := internal.NewRouter(projectID)
    if err != nil {
        log.Fatalf("Failed to create router: %v", err)
    }

    // Setup routes
    if err := router.SetupRoutes(); err != nil {
        log.Fatalf("Failed to setup routes: %v", err)
    }

    // Get port from config
    port := config.AppConfig.Server.Port

    log.Printf("Server starting on port %s", port)
    log.Fatal(http.ListenAndServe(":"+port, nil))
}

// internal/routes.go
package internal

import (
    "log"
    "net/http"
    "path/filepath"
    "strings"
    "swing-society-website/server/internal/api/handlers"
    "swing-society-website/server/internal/config"
    "swing-society-website/server/internal/middleware"
    "swing-society-website/server/internal/storage"
)

type Router struct {
    mw          *middleware.MiddlewareManager
    rateLimiter *middleware.IPRateLimiter
}

func NewRouter(projectID string) (*Router, error) {
    r := &Router{
        mw:          middleware.NewMiddlewareManager(),
        rateLimiter: middleware.NewIPRateLimiter(),
    }

    // Add global middleware
    r.mw.UseGlobal(
        middleware.SecurityHeaders,
        middleware.Logger,
    )

    return r, nil
}

func createFileServer(dir, contentType string) http.Handler {
	fileServer := http.FileServer(http.Dir(dir))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			// Set content type if specified
			if contentType != "" {
					w.Header().Set("Content-Type", contentType)
			}
			fileServer.ServeHTTP(w, r)
	})
}

func (r *Router) SetupRoutes() error {
    // Create middleware chains
    apiChain := middleware.NewChain().
        Add(r.rateLimiter.RateLimitMiddleware)

    staticChain := middleware.NewChain().
        Add(r.rateLimiter.RateLimitMiddleware)

    // Initialize all storage implementations
    googleStorage := storage.NewGoogleSheetsStorage(config.AppConfig.External.GoogleSheetsURL)
    jsonStorage := storage.NewJSONFileStorage(filepath.Join(config.AppConfig.Paths.DataDir, "carousel.json"))
    registrationStorage := storage.NewSimpleRegistrationStorage()
    classStorage := storage.NewSimpleClassStorage()
    templateStorage := storage.NewFileTemplateStorage()
    newsletterStorage := storage.NewSimpleNewsletterStorage()
    contactStorage := storage.NewSimpleContactStorage()

    // Initialize all handlers with their dependencies
    carouselHandler := handlers.NewCarouselHandler(googleStorage, jsonStorage)
    registrationHandler := handlers.NewRegistrationHandler(registrationStorage)
    classHandler := handlers.NewClassHandler(classStorage)
    templateHandler := handlers.NewTemplateHandler(templateStorage)
    newsletterHandler := handlers.NewNewsletterHandler(newsletterStorage)
    contactHandler := handlers.NewContactHandler(contactStorage)

    // Health check endpoint (no rate limiting)
    r.mw.AddHandler("/health", http.HandlerFunc(handlers.HandleHealth))

    // API routes (with rate limiting)
    r.mw.AddHandler("/api/carousel/", 
        http.HandlerFunc(carouselHandler.ServeCarousel), 
        apiChain.GetMiddlewares()...)

    r.mw.AddHandler("/api/register", 
        http.HandlerFunc(registrationHandler.HandleRegistration), 
        apiChain.GetMiddlewares()...)

    r.mw.AddHandler("/api/class", 
        http.HandlerFunc(classHandler.HandleClass), 
        apiChain.GetMiddlewares()...)

    r.mw.AddHandler("/api/newsletter", 
        http.HandlerFunc(newsletterHandler.HandleNewsletter), 
        apiChain.GetMiddlewares()...)

    r.mw.AddHandler("/api/contact", 
        http.HandlerFunc(contactHandler.HandleContact), 
        apiChain.GetMiddlewares()...)

		// In your SetupRoutes method, replace the static handlers with:
		staticDir := config.AppConfig.Paths.StaticDir

		// Static file handlers (with caching and rate limiting)
		staticHandler := http.StripPrefix("/static/", createFileServer(staticDir, ""))
		r.mw.AddHandler("/static/", staticHandler, staticChain.GetMiddlewares()...)

		// CSS files handler with proper MIME type
		cssHandler := http.StripPrefix("/css/", createFileServer(staticDir, "text/css"))
		r.mw.AddHandler("/css/", cssHandler, staticChain.GetMiddlewares()...)

		// JavaScript files handler with proper MIME type
		jsHandler := http.StripPrefix("/js/", createFileServer(staticDir, "application/javascript"))
		r.mw.AddHandler("/js/", jsHandler, staticChain.GetMiddlewares()...)

    // Template route
    r.mw.AddHandler("/templates/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        templateHandler.HandleTemplate(w, r, r.URL.Path)
    }))

    // Root handler - must be registered last to avoid overriding other routes
    r.mw.AddHandler("/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        // Skip API and other specific paths
        if strings.HasPrefix(r.URL.Path, "/api/") || 
           strings.HasPrefix(r.URL.Path, "/static/") ||
           strings.HasPrefix(r.URL.Path, "/css/") ||
           strings.HasPrefix(r.URL.Path, "/js/") ||
           strings.HasPrefix(r.URL.Path, "/templates/") {
            return
        }

        log.Printf("Root handler serving index.html for path: %s", r.URL.Path)
        indexPath := filepath.Join(config.AppConfig.Paths.TemplatesDir, "index.html")
        http.ServeFile(w, r, indexPath)
    }))

    // Register all handlers with http package
    registeredHandlers := r.mw.GetHandlers()
    for _, h := range registeredHandlers {
        handler := r.mw.BuildHandler(h.Path, h.Handler, h.Middlewares...)
        http.Handle(h.Path, handler)
    }

    return nil
}

package internal

import (
    "log"
		"mime"
    "net/http"
		"path/filepath"
    "swing-society-website/server/internal/config"
)

func init() {
	// Register common MIME types
	mime.AddExtensionType(".css", "text/css")
	mime.AddExtensionType(".js", "application/javascript")
	mime.AddExtensionType(".html", "text/html")
	mime.AddExtensionType(".png", "image/png")
	mime.AddExtensionType(".jpg", "image/jpeg")
	mime.AddExtensionType(".jpeg", "image/jpeg")
	mime.AddExtensionType(".gif", "image/gif")
	mime.AddExtensionType(".svg", "image/svg+xml")
}


func ServeFiles() {
	fs := http.FileServer(http.Dir(config.AppConfig.Paths.StaticDir))

	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			path := filepath.Clean(r.URL.Path)
			ext := filepath.Ext(path)

			if mimeType := mime.TypeByExtension(ext); mimeType != "" {
					w.Header().Set("Content-Type", mimeType)
			}

			// Cache control based on environment
			if config.AppConfig.Environment == "development" {
					w.Header().Set("Cache-Control", "no-cache, no-store, must-revalidate")
					w.Header().Set("Pragma", "no-cache")
					w.Header().Set("Expires", "0")
			} else {
					w.Header().Set("Cache-Control", "public, max-age=31536000")
			}

			log.Printf("Serving static file: %s", path)
			fs.ServeHTTP(w, r)
	})

	http.Handle("/static/", http.StripPrefix("/static/", handler))
}

package middleware

import (
		"log"
    "net/http"
		"strings"
		"swing-society-website/server/internal/config"
)

// SecurityHeaders adds security-related HTTP headers to all responses
func SecurityHeaders(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        // Use CSP directives from config
        w.Header().Set("Content-Security-Policy", config.AppConfig.Security.CSPDirectives)
				w.Header().Set("X-Content-Security-Policy", config.AppConfig.Security.CSPDirectives)



        // Use allowed origins from config
        if len(config.AppConfig.Security.AllowedOrigins) > 0 {
            w.Header().Set("Access-Control-Allow-Origin", 
                strings.Join(config.AppConfig.Security.AllowedOrigins, ", "))
        }


				cspDirectives := "default-src 'self' https:; " +
				"script-src 'self' 'unsafe-inline' https://unpkg.com; " +
				"style-src 'self' 'unsafe-inline' https:; " +
				"img-src 'self' https: data:; " +
				"font-src 'self' data: https:; " +  // Added font-src directive
				"frame-src 'self' https://www.youtube.com; " +
				"connect-src 'self' https:;"


        // Standard security headers
        w.Header().Set("X-Frame-Options", "SAMEORIGIN")
        w.Header().Set("X-XSS-Protection", "1; mode=block")
        w.Header().Set("X-Content-Type-Options", "nosniff")
        w.Header().Set("Referrer-Policy", "strict-origin-when-cross-origin")
				w.Header().Set("Content-Security-Policty", cspDirectives)
        w.Header().Set("Permissions-Policy", "microphone=(), camera=()")
        w.Header().Set("Strict-Transport-Security", "max-age=31536000; includeSubDomains")

        next.ServeHTTP(w, r)
    })
}

// Logger middleware for request logging
func Logger(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        // Log request details
        log.Printf("[%s] %s %s %s", 
            r.RemoteAddr, 
            r.Method, 
            r.URL.Path,
            r.UserAgent(),
        )

        next.ServeHTTP(w, r)
    })
}

// internal/middleware/chain.go
package middleware

import (
    "log"
    "net/http"
    "time"
)

// Middleware represents a middleware function
type Middleware func(http.Handler) http.Handler

// Chain holds a list of middleware to be executed in order
type Chain struct {
    middlewares []Middleware
}

// NewChain creates a new middleware chain
func NewChain() *Chain {
    return &Chain{
        middlewares: make([]Middleware, 0),
    }
}

// Add appends a middleware to the chain
func (c *Chain) Add(middleware Middleware) *Chain {
    c.middlewares = append(c.middlewares, middleware)
    return c
}

// GetMiddlewares returns the slice of middlewares
func (c *Chain) GetMiddlewares() []Middleware {
    return c.middlewares
}

// AddIf adds a middleware conditionally
func (c *Chain) AddIf(condition bool, middleware Middleware) *Chain {
    if condition {
        return c.Add(middleware)
    }
    return c
}

// Then executes the middleware chain and ends with the final handler
func (c *Chain) Then(h http.Handler) http.Handler {
    if h == nil {
        h = http.DefaultServeMux
    }

    // Execute middlewares in reverse order
    for i := len(c.middlewares) - 1; i >= 0; i-- {
        h = c.middlewares[i](h)
    }

    return h
}

// Handler represents any HTTP handler with additional context
type Handler struct {
    Path        string
    Handler     http.Handler
    Middlewares []Middleware
}

// MiddlewareManager manages middleware chains for different routes
type MiddlewareManager struct {
    globalChain *Chain
    handlers    []Handler
}

// NewMiddlewareManager creates a new middleware manager
func NewMiddlewareManager() *MiddlewareManager {
    return &MiddlewareManager{
        globalChain: NewChain(),
        handlers:    make([]Handler, 0),
    }
}

// UseGlobal adds middleware to the global chain
func (m *MiddlewareManager) UseGlobal(middleware ...Middleware) {
    for _, mw := range middleware {
        m.globalChain.Add(mw)
    }
}

// AddHandler adds a handler with its specific middleware
func (m *MiddlewareManager) AddHandler(path string, handler http.Handler, middleware ...Middleware) {
    m.handlers = append(m.handlers, Handler{
        Path:        path,
        Handler:     handler,
        Middlewares: middleware,
    })
}

// BuildHandler builds the final handler with all middleware applied
func (m *MiddlewareManager) BuildHandler(path string, handler http.Handler, middleware ...Middleware) http.Handler {
    // Create a new chain with global middleware
    chain := NewChain()

    // Add logging middleware
    chain.Add(func(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
            start := time.Now()
            log.Printf("Started %s %s", r.Method, r.URL.Path)
            next.ServeHTTP(w, r)
            log.Printf("Completed %s %s in %v", r.Method, r.URL.Path, time.Since(start))
        })
    })

    // Add global middleware
    for _, mw := range m.globalChain.middlewares {
        chain.Add(mw)
    }

    // Add route-specific middleware
    for _, mw := range middleware {
        chain.Add(mw)
    }

    return chain.Then(handler)
}

func (m *MiddlewareManager) GetHandlers() []Handler {
	return m.handlers
}

package middleware

import (
	"log"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	"swing-society-website/server/internal/config"

	"golang.org/x/time/rate"
)

type visitor struct {
	limiter  *rate.Limiter
	lastSeen time.Time
}

type IPRateLimiter struct {
	ips map[string]*visitor
	mu  *sync.RWMutex
}

func NewIPRateLimiter() *IPRateLimiter {
	i := &IPRateLimiter{
		ips: make(map[string]*visitor),
		mu:  &sync.RWMutex{},
	}

	go i.cleanupVisitors()
	return i
}

// parseRateLimit parses rate limit strings like "100-M" (100 per minute)
func parseRateLimit(limit string) (rate.Limit, int) {
	parts := strings.Split(limit, "-")
	if len(parts) != 2 {
		return rate.Limit(1), 1 // default fallback
	}

	requestsPerPeriod, _ := strconv.Atoi(parts[0])
	period := strings.ToUpper(parts[1])

	switch period {
	case "S":
		return rate.Limit(requestsPerPeriod), requestsPerPeriod
	case "M":
		return rate.Every(time.Minute / time.Duration(requestsPerPeriod)), requestsPerPeriod
	case "H":
		return rate.Every(time.Hour / time.Duration(requestsPerPeriod)), requestsPerPeriod
	default:
		return rate.Limit(1), 1
	}
}

func (i *IPRateLimiter) GetLimiter(ip string, path string) *rate.Limiter {
	i.mu.Lock()
	defer i.mu.Unlock()

	key := ip + path
	v, exists := i.ips[key]

	if !exists {
		// Get rate limit from config based on path
		limitStr := config.AppConfig.Security.RateLimits["default"]

		// Apply specific limits based on path
		if strings.HasPrefix(path, "/api/") {
			limitStr = config.AppConfig.Security.RateLimits["api"]
		} else if strings.HasPrefix(path, "/static/") {
			limitStr = config.AppConfig.Security.RateLimits["static"]
		}

		rateLimit, burst := parseRateLimit(limitStr)
		limiter := rate.NewLimiter(rateLimit, burst)

		v = &visitor{
			limiter:  limiter,
			lastSeen: time.Now(),
		}
		i.ips[key] = v
		log.Printf("New rate limiter created for IP: %s, Path: %s", ip, path)
	}

	v.lastSeen = time.Now()
	return v.limiter
}

func (i *IPRateLimiter) cleanupVisitors() {
	for {
		time.Sleep(time.Minute * 5)
		i.mu.Lock()
		for key, v := range i.ips {
			if time.Since(v.lastSeen) > time.Hour {
				delete(i.ips, key)
			}
		}
		i.mu.Unlock()
	}
}

// RateLimitMiddleware is an HTTP middleware that enforces rate limiting.
// If the request exceeds the allowed rate, it responds with HTTP 429.
func (i *IPRateLimiter) RateLimitMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			ip := r.RemoteAddr
			limiter := i.GetLimiter(ip, r.URL.Path)
			if !limiter.Allow() {
					http.Error(w, "429 Too Many Requests", http.StatusTooManyRequests)
					return
			}
			next.ServeHTTP(w, r)
	})
}

