package handlers

import (
	"encoding/csv"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"strings"
)

// CarouselItem represents a single item in the carousel
type CarouselItem struct {
	ImageURL string `json:"image_url"`
	Caption  string `json:"caption"`
	Type     string `json:"type"`
}




// Convert Google Drive Links to Direct Image URLs
func ConvertGoogleDriveLink(url string) string {
	if strings.Contains(url, "drive.google.com/file/d/") {
		parts := strings.Split(url, "/")
		if len(parts) >= 5 {
			fileID := parts[5] // Extract the file ID
			return "https://drive.google.com/uc?export=view&id=" + fileID
		}
	}
	return url // Return original if not a Drive link
}

// Fetch Carousel Data from Google Sheets
func FetchFromGoogleSheets() ([]CarouselItem, error) {
	googleSheetsURL := os.Getenv("GOOGLE_SHEETS_CSV_URL")
	if googleSheetsURL == "" {
		return nil, fmt.Errorf("Google Sheets URL is not set")
	}

	resp, err := http.Get(googleSheetsURL)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	reader := csv.NewReader(resp.Body)
	var items []CarouselItem

	// Skip header row
	_, _ = reader.Read()

	for {
		record, err := reader.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}

		item := CarouselItem{
			ImageURL: ConvertGoogleDriveLink(record[0]), // Convert Drive links
			Caption:  record[1],
			Type:     strings.ToLower(record[2]), // Normalize type
		}
		items = append(items, item)
	}
	return items, nil
}

// Fetch Carousel Data from Local JSON
func FetchFromJSON() ([]CarouselItem, error) {
	file, err := os.Open("data/carousel.json")
	if err != nil {
		return nil, err
	}
	defer file.Close()

	log.Println("Loading JSON data from carousel.json...")
	log.Println("File Path: static/data/carousel.json")

	var items []CarouselItem
	decoder := json.NewDecoder(file)
	if err := decoder.Decode(&items); err != nil {
		return nil, err
	}
	return items, nil
}

// Fetch Carousel Data with Fallback
func FetchCarouselData() ([]CarouselItem, error) {

	data, err := FetchFromGoogleSheets()
	if err == nil {
		return data, nil
	}

	log.Println("⚠️ Google Sheets failed, using fallback JSON.")
	log.Println("Data before filtering:", data)

	// Try fetching from JSON
	jsonData, jsonErr := FetchFromJSON()
	if jsonErr != nil {
		log.Println("❌ Both Google Sheets and JSON failed.")
		return []CarouselItem{
			{ImageURL: "/static/images/default.jpg", Caption: "Error loading images", Type: "default"},
		}, nil
	}

	return jsonData, nil
}

// Serve Carousel Data for Frontend Requests
func ServeCarousel(w http.ResponseWriter, r *http.Request) {
	carouselType := strings.TrimPrefix(r.URL.Path, "/carousel/")
	carouselType = strings.ToLower(carouselType) // Normalize type


	log.Println("Received request for carousel data - Type:", carouselType) // Debug log



	data, err := FetchCarouselData()
	if err != nil {
		log.Println("Error loading carousel data:", err) // Debug log
		http.Error(w, "Error fetching carousel data", http.StatusInternalServerError)
		return
	}

	log.Println("Carousel data fetched:", data	) // Debug: Print all items loaded
	var filteredItems []CarouselItem
	for _, item := range data {
		if item.Type == carouselType {
			filteredItems = append(filteredItems, item)
		}
	}

	// Debug: If no items are found, log it
	if len(filteredItems) == 0 {
		log.Println("⚠️ No items found for type:", carouselType)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(filteredItems)
	if err != nil {
		log.Println("Error encoding JSON:", err) // Debug log
	}
}



// Render empty carousel with a message
func renderEmptyCarousel(w http.ResponseWriter, carouselType string) {
	html := fmt.Sprintf(`
	<div class="carousel" aria-label="Carousel Component" data-carousel="%s">
			<div class="carousel-inner">
					<div class="carousel-item">
							<p>No carousel items found for type: %s</p>
					</div>
			</div>
	</div>`, carouselType, carouselType)

	w.Header().Set("Content-Type", "text/html")
	fmt.Fprint(w, html)
}

// Render populated carousel with items
func renderCarousel(w http.ResponseWriter, items []CarouselItem, carouselType string) {
	var itemsHTML strings.Builder

	for _, item := range items {
			if item.Type == "image" || item.ImageURL != "" {
					itemsHTML.WriteString(fmt.Sprintf(`
					<div class="carousel-item">
							<img src="%s" alt="%s">
					</div>`, item.ImageURL, item.Caption))
			} else if item.Type == "video" {
					itemsHTML.WriteString(fmt.Sprintf(`
					<div class="carousel-item">
							<video controls>
									<source src="%s" type="video/mp4">
									Your browser does not support the video tag.
							</video>
					</div>`, item.ImageURL))
			} else {
					itemsHTML.WriteString(fmt.Sprintf(`
					<div class="carousel-item">
							<h3>%s</h3>
					</div>`, item.Caption))
			}
	}

	html := fmt.Sprintf(`
	<div class="carousel" aria-label="Carousel Component" data-carousel="%s">
			<div class="carousel-inner">
					%s
			</div>
			<button class="carousel-control prev" aria-label="Previous Slide">&#10094;</button>
			<button class="carousel-control next" aria-label="Next Slide">&#10095;</button>
	</div>`, carouselType, itemsHTML.String())

	w.Header().Set("Content-Type", "text/html")
	fmt.Fprint(w, html)
}

