package middleware

import (
	"log"
	"net/http"
	"strings"
	"sync"
	"time"

	"golang.org/x/time/rate"
)

type IPRateLimiter struct {
    ips map[string]*visitor
    mu  *sync.RWMutex
}

type visitor struct {
    limiter  *rate.Limiter
    lastSeen time.Time
}

func NewIPRateLimiter() *IPRateLimiter {
    i := &IPRateLimiter{
        ips: make(map[string]*visitor),
        mu:  &sync.RWMutex{},
    }

    // Start cleanup routine
    go i.cleanupVisitors()

    return i
}

func (i *IPRateLimiter) GetLimiter(ip string, path string) *rate.Limiter {
    i.mu.Lock()
    defer i.mu.Unlock()

		key := ip + path // Use both IP and path for more granular rate limiting
    v, exists := i.ips[ip]

		if !exists {
			var limiter *rate.Limiter

			// Different rate limits based on path type
			if strings.HasPrefix(path, "/templates/") {
					// More permissive limits for template requests
					limiter = rate.NewLimiter(rate.Limit(5), 10) // 5 requests per second, burst of 10
			} else if strings.HasPrefix(path, "/api/") {
					// Stricter limits for API endpoints
					limiter = rate.NewLimiter(rate.Every(200*time.Second), 5)
			} else {
					// Default limits for other paths
					limiter = rate.NewLimiter(rate.Every(60*time.Second), 20)
			}

			v = &visitor{
					limiter:  limiter,
					lastSeen: time.Now(),
			}
			i.ips[key] = v
			log.Printf("New rate limiter created for IP: %s, Path: %s", ip, path)
		}

		v.lastSeen = time.Now()
    return v.limiter
}

func (i *IPRateLimiter) RateLimit(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        // Only apply rate limiting to specific paths
        if !shouldRateLimit(r.URL.Path) {
            next.ServeHTTP(w, r)
            return
        }

        ip := getIP(r)
				path := r.URL.Path
        limiter := i.GetLimiter(ip, path)

        if !limiter.Allow() {
            log.Printf("Rate limit exceeded for IP: %s on path: %s", ip, r.URL.Path)
            w.Header().Set("Retry-After", "2")
            http.Error(w, "Too Many Requests", http.StatusTooManyRequests)
            return
        }

        next.ServeHTTP(w, r)
    })
}

// shouldRateLimit determines if the path should be rate limited
func shouldRateLimit(path string) bool {
    // Rate limit API endpoints and form submissions
    if strings.HasPrefix(path, "/api/") || 
       strings.HasPrefix(path, "/submit/") ||
       strings.HasPrefix(path, "/contact/") ||
			 strings.HasPrefix(path, "/templates/") {
        return true
    }

    // Don't rate limit static assets
    if strings.HasPrefix(path, "/static/") {
        return false
    }

    // Rate limit the initial page load (but with generous limits)
    return path == "/" || path == "/index.html"
}

func getIP(r *http.Request) string {
    // Get IP from various headers or remote addr
    ip := r.Header.Get("X-Real-IP")
    if ip == "" {
        ip = r.Header.Get("X-Forwarded-For")
    }
    if ip == "" {
        ip = strings.Split(r.RemoteAddr, ":")[0]
    }
    return ip
}

func (i *IPRateLimiter) cleanupVisitors() {
    for {
        time.Sleep(5 * time.Minute)
        i.mu.Lock()
        for key, v := range i.ips {
            if time.Since(v.lastSeen) > 10*time.Minute {
                delete(i.ips, key)
                log.Printf("Cleaned up rate limiter for IP: %s", key)
            }
        }
        i.mu.Unlock()
    }
}

package middleware

import (
		"log"
    "net/http"
)

// SecurityHeaders adds security-related HTTP headers to all responses
func SecurityHeaders(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			// Define security headers
			headers := map[string]string{
				"X-Frame-Options":           "SAMEORIGIN",
				"X-XSS-Protection":          "1; mode=block",
				"X-Content-Type-Options":    "nosniff",
				"Referrer-Policy":           "strict-origin-when-cross-origin",
				"Content-Security-Policy":   "default-src 'self' https:; " +
																		"script-src 'self' 'unsafe-inline' https://unpkg.com; " +
																		"style-src 'self' 'unsafe-inline' https:; " +
																		"img-src 'self' https: data:; " +
																		"frame-src 'self' https://www.youtube.com; " +
																		"connect-src 'self' https:;",
				"Permissions-Policy":        "microphone=(), camera=()",  // Removed unnecessary restrictions
				"Strict-Transport-Security": "max-age=31536000; includeSubDomains",
		}

        // Set all security headers
        for key, value := range headers {
            w.Header().Set(key, value)
        }

        next.ServeHTTP(w, r)
    })
}

// Logger middleware for request logging
func Logger(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        // Log request details
        log.Printf("[%s] %s %s %s", 
            r.RemoteAddr, 
            r.Method, 
            r.URL.Path,
            r.UserAgent(),
        )

        next.ServeHTTP(w, r)
    })
}

package config

import (
    "log"
    "os"
    "path/filepath"
    "strings"
)

type Paths struct {
    RootDir      string
    TemplatesDir string
    StaticDir    string
}

var AppPaths *Paths

func InitPaths() {
    var rootDir string

    // Check if we're in Docker/Cloud Run
    if os.Getenv("DOCKER_CONTAINER") == "true" {
        rootDir = "/app"
    } else {
        // Development environment
        serverDir, err := os.Getwd()
        if err != nil {
            log.Fatalf("Failed to get current working directory: %v", err)
        }

        // Find project root
        rootDir = findProjectRoot(serverDir)
    }

    AppPaths = &Paths{
        RootDir:      rootDir,
        TemplatesDir: filepath.Join(rootDir, "templates"),
        StaticDir:    filepath.Join(rootDir, "static"),
    }

    // Log paths for debugging
    log.Printf("Root Dir: %s", AppPaths.RootDir)
    log.Printf("Templates Dir: %s", AppPaths.TemplatesDir)
    log.Printf("Static Dir: %s", AppPaths.StaticDir)

    // Create directories if they don't exist in development mode
    if os.Getenv("DOCKER_CONTAINER") != "true" {
			os.MkdirAll(AppPaths.TemplatesDir, 0755)
			os.MkdirAll(AppPaths.StaticDir, 0755)
    }

    // Verify directories exist
    verifyDir(AppPaths.TemplatesDir, "Templates")
    verifyDir(AppPaths.StaticDir, "Static")
}

// findProjectRoot looks for go.mod file to determine project root
func findProjectRoot(dir string) string {
    // Check if this is the project directory (contains go.mod)
    if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
        return dir
    }

    // If we're in the server directory, go up one level
    if strings.HasSuffix(dir, "server") {
        parentDir := filepath.Dir(dir)
        // Check if parent directory has go.mod
        if _, err := os.Stat(filepath.Join(parentDir, "go.mod")); err == nil {
            return parentDir
        }
    }

    // If we can't find go.mod, use the directory above server/
    if strings.HasSuffix(dir, "server") {
        return filepath.Dir(dir)
    }

    // Default to current directory if we can't determine project root
    return dir
}

func verifyDir(path string, name string) {
    if _, err := os.Stat(path); os.IsNotExist(err) {
        log.Printf("Warning: %s directory not found at: %s", name, path)
    } else {
        log.Printf("%s directory found at: %s", name, path)
    }
}

