type Router struct{}

func NewRouter(projectID string) (*Router, error) {
    router := &Router{}

    // Initialize rate limiter middleware
    rateLimiter := middleware.NewIPRateLimiter()

    // Health check endpoint (no rate limiting needed)
    http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Content-Type", "application/json")
        w.WriteHeader(http.StatusOK)
        w.Write([]byte(`{
            "status": "ok",
            "environment": "` + config.AppConfig.Environment + `",
            "version": "1.0.0"
        }`))
    })

    // Static file handlers (rate-limited)
    http.Handle("/css/", rateLimiter.RateLimitMiddleware(http.HandlerFunc(serveStatic("text/css"))))
    http.Handle("/js/", rateLimiter.RateLimitMiddleware(http.HandlerFunc(serveStatic("application/javascript"))))
    http.Handle("/static/", rateLimiter.RateLimitMiddleware(http.StripPrefix("/static/", http.FileServer(http.Dir(config.AppConfig.Paths.StaticDir)))))

    // API routes (all protected with rate limiting)
    http.Handle("/api/register", rateLimiter.RateLimitMiddleware(http.HandlerFunc(handlers.HandleRegistration)))
    http.Handle("/api/contact", rateLimiter.RateLimitMiddleware(http.HandlerFunc(handlers.HandleContact)))
    http.Handle("/api/newsletter", rateLimiter.RateLimitMiddleware(http.HandlerFunc(handlers.HandleNewsletter)))
    http.Handle("/api/class", rateLimiter.RateLimitMiddleware(http.HandlerFunc(handlers.HandleClass)))
    http.Handle("/api/carousel/", rateLimiter.RateLimitMiddleware(http.HandlerFunc(handlers.ServeCarousel)))

    // Template routes
    http.HandleFunc("/templates/", handleTemplateRequest)

    // Root handler
    http.HandleFunc("/", handleRoot)

    return router, nil
}

// Serve static files with correct Content-Type
func serveStatic(contentType string) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        file := filepath.Join(config.AppConfig.Paths.StaticDir, r.URL.Path)
        w.Header().Set("Content-Type", contentType)
        http.ServeFile(w, r, file)
    }
}

// Handles template requests (serving HTML dynamically)
func handleTemplateRequest(w http.ResponseWriter, r *http.Request) {
    log.Printf("Template request received: %s", r.URL.Path)

    if r.Header.Get("HX-Request") == "true" {
        handlers.HandleTemplate(w, r, r.URL.Path)
        return
    }

    indexPath := filepath.Join(config.AppConfig.Paths.TemplatesDir, "index.html")
    http.ServeFile(w, r, indexPath)
}

// Handles root requests, ensuring API requests are not overridden
func handleRoot(w http.ResponseWriter, r *http.Request) {
    if strings.HasPrefix(r.URL.Path, "/api/") {
        return // Let API handlers handle these routes
    }

    indexPath := filepath.Join(config.AppConfig.Paths.TemplatesDir, "index.html")
    log.Printf("Serving index.html for path: %s", r.URL.Path)
    http.ServeFile(w, r, indexPath)
}

