    cleanPath := strings.TrimPrefix(templatePath, "/templates")
    fullPath := filepath.Join(config.AppConfig.Paths.TemplatesDir, cleanPath)

    w.Header().Set("Cache-Control", "private, max-age=10")

    if _, err := os.Stat(fullPath); os.IsNotExist(err) {
        response.Error(w, customerrors.NewAppError(
            customerrors.ErrorTypeFileSystem,
            "Template not found",
            err,
            map[string]string{"path": cleanPath},
        ))
        return
    }

    // For HTMX requests, serve the template fragment
    if r.Header.Get("HX-Request") == "true" {
        http.ServeFile(w, r, fullPath)
        return
    }

    // For regular requests, serve the full page
    indexPath := filepath.Join(config.AppConfig.Paths.TemplatesDir, "index.html")
    http.ServeFile(w, r, indexPath)
}

