    carouselType = strings.ToLower(carouselType)

    log.Printf("Received request for carousel data - Type: %s", carouselType)

    data, err := FetchCarouselData()
    if err != nil {
        response.Error(w, customerrors.NewInternalError(
            "Error fetching carousel data",
            err,
        ))
        return
    }

    var filteredItems []models.CarouselItem
    for _, item := range data {
        if item.Type == carouselType {
            filteredItems = append(filteredItems, item)
        }
    }

    response.JSON(w, http.StatusOK, filteredItems)
}

// Convert Google Drive Links to Direct Image URLs
func ConvertGoogleDriveLink(url string) string {
    if strings.Contains(url, "drive.google.com/file/d/") {
        parts := strings.Split(url, "/")
        if len(parts) >= 5 {
            fileID := parts[5]
            return "https://drive.google.com/uc?export=view&id=" + fileID
        }
    }
    return url
}

// Fetch Carousel Data from Google Sheets
func FetchFromGoogleSheets() ([]models.CarouselItem, error) {
    googleSheetsURL := os.Getenv("GOOGLE_SHEETS_CSV_URL")
    if googleSheetsURL == "" {
        return nil, fmt.Errorf("Google Sheets URL is not set")
    }

    resp, err := http.Get(googleSheetsURL)
    if err != nil {
        return nil, err
    }
    defer resp.Body.Close()

    reader := csv.NewReader(resp.Body)
    var items []models.CarouselItem

    // Skip header row
    _, _ = reader.Read()

    for {
        record, err := reader.Read()
        if err == io.EOF {
            break
        }
        if err != nil {
            return nil, err
        }

        item := models.CarouselItem{
            ImageURL: ConvertGoogleDriveLink(record[0]),
            Caption:  record[1],
            Type:     strings.ToLower(record[2]),
        }

        if errors := item.Validate(); len(errors) > 0 {
            log.Printf("Warning: Skipping invalid carousel item: %v", errors)
            continue
        }

        items = append(items, item)
    }
    return items, nil
}

// Fetch Carousel Data from Local JSON
func FetchFromJSON() ([]models.CarouselItem, error) {
    file, err := os.Open("data/carousel.json")
    if err != nil {
        return nil, err
    }
    defer file.Close()

    var items []models.CarouselItem
    decoder := json.NewDecoder(file)
    if err := decoder.Decode(&items); err != nil {
        return nil, err
    }

    // Validate all items
    validItems := make([]models.CarouselItem, 0)
    for _, item := range items {
        if errors := item.Validate(); len(errors) == 0 {
            validItems = append(validItems, item)
        } else {
            log.Printf("Warning: Skipping invalid carousel item: %v", errors)
        }
    }

    return validItems, nil
}

// FetchCarouselData with error handling
func FetchCarouselData() ([]models.CarouselItem, error) {
    // Try Google Sheets first
    data, err := FetchFromGoogleSheets()
    if err == nil {
        return data, nil
    }

    log.Printf("⚠️ Google Sheets failed, using fallback JSON: %v", err)

    // Try fetching from JSON
    jsonData, jsonErr := FetchFromJSON()
    if jsonErr != nil {
        log.Printf("❌ Both Google Sheets and JSON failed: %v", jsonErr)
        return nil, customerrors.NewInternalError(
            "Failed to fetch carousel data from all sources",
            jsonErr,
        )
    }

    return jsonData, nil
}

