func loadConfigFile(config *Config) error {
    env := os.Getenv("ENVIRONMENT")
    if env == "" {
        env = "development"
    }

    // Look for config file in several locations
    configPaths := []string{
        fmt.Sprintf("config/environments/%s.json", env),
        fmt.Sprintf("server/config/environments/%s.json", env),
        fmt.Sprintf("../config/environments/%s.json", env),
    }

    var loadError error
    for _, configPath := range configPaths {
        file, err := os.Open(configPath)
        if err != nil {
            loadError = err
            continue
        }
        defer file.Close()

        decoder := json.NewDecoder(file)
        if err := decoder.Decode(config); err != nil {
            loadError = err
            continue
        }

        log.Printf("Loaded configuration from %s", configPath)
        return nil
    }

    return fmt.Errorf("failed to load config file: %v", loadError)
}

