)

type Router struct {
    mw *middleware.MiddlewareManager
}

func NewRouter(projectID string) (*Router, error) {
    router := &Router{
        mw: middleware.NewMiddlewareManager(),
    }

    // Add global middleware
    router.mw.UseGlobal(
        middleware.SecurityHeaders,
        middleware.Logger,
    )

    return router, nil
}

func (r *Router) SetupRoutes() {
    // API routes with rate limiting and security
    apiChain := middleware.NewChain().
        Add(middleware.NewIPRateLimiter().RateLimit)

    // Static files with caching and rate limiting
    staticChain := middleware.NewChain().
        Add(middleware.NewIPRateLimiter().RateLimit)

    // Register routes with specific middleware
    r.mw.AddHandler("/api/register", 
        http.HandlerFunc(handlers.HandleRegistration),
        apiChain.middlewares...)

    r.mw.AddHandler("/api/contact", 
        http.HandlerFunc(handlers.HandleContact),
        apiChain.middlewares...)

    r.mw.AddHandler("/api/newsletter", 
        http.HandlerFunc(handlers.HandleNewsletter),
        apiChain.middlewares...)

    r.mw.AddHandler("/api/class", 
        http.HandlerFunc(handlers.HandleClass),
        apiChain.middlewares...)

    r.mw.AddHandler("/api/carousel/", 
        http.HandlerFunc(handlers.ServeCarousel),
        apiChain.middlewares...)

    // Templates with rate limiting
    r.mw.AddHandler("/templates/", 
        http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
            handlers.HandleTemplate(w, r, r.URL.Path)
        }),
        apiChain.middlewares...)

    // Static files
    staticHandler := http.StripPrefix("/static/", 
        http.FileServer(http.Dir(config.AppConfig.Paths.StaticDir)))
    r.mw.AddHandler("/static/", staticHandler, staticChain.middlewares...)

    // Health check
    r.mw.AddHandler("/health", http.HandlerFunc(handlers.HandleHealth))

    // Register all routes with http package
    for _, h := range r.mw.handlers {
        http.Handle(h.Path, r.mw.BuildHandler(h.Path, h.Handler, h.Middlewares...))
    }
}

