    if !h.storage.TemplateExists(cleanPath) {
        response.Error(w, customerrors.NewAppError(
            customerrors.ErrorTypeFileSystem,
            "Template not found",
            nil,
            map[string]string{"path": cleanPath},
        ))
        return
