        w.Header().Set("Permissions-Policy", "microphone=(), camera=()")
        w.Header().Set("Strict-Transport-Security", "max-age=31536000; includeSubDomains")

        // For CSS files, ensure the correct MIME type is set
        if strings.HasSuffix(r.URL.Path, ".css") {
            w.Header().Set("Content-Type", "text/css")
        }

        next.ServeHTTP(w, r)
    })
}

// Update the createFileServer function in routes.go

func createFileServer(dir, contentType string) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        // Get the requested path
        path := r.URL.Path
        fullPath := filepath.Join(dir, path)

        // Determine content type based on file extension if not specified
        if contentType == "" {
            ext := filepath.Ext(path)
            switch ext {
            case ".css":
                contentType = "text/css"
            case ".js":
                contentType = "application/javascript"
            case ".html":
                contentType = "text/html"
            case ".json":
                contentType = "application/json"
            }
        }

        // Set content type if determined
        if contentType != "" {
            w.Header().Set("Content-Type", contentType)
        }

        // Check if file exists
        if _, err := os.Stat(fullPath); os.IsNotExist(err) {
            http.NotFound(w, r)
            return
        }

        // Serve the file
        http.ServeFile(w, r, fullPath)
    })
}

